#include "resident/kernel/catalog_section_observation.hpp"
// 目录仅选择原私人模板的三句本人声明，不读全族谱，也不把选项或玩家话当NPC意愿。
#include "collateral_control_catalog.hpp"
#include "succession_personal_assets.hpp"
#include <set>
namespace hanmo::resident {namespace {
bool reference(const StableId& id){return !id.empty()&&id.size()<=256;}
Status definition_shape(const CollateralControlDefinition& d){for(const auto* id:{&d.id,&d.template_id,&d.recognize_node_id,&d.accept_node_id,&d.revoke_node_id})if(!reference(*id))return common_failure("InvalidCollateralControlDefinition");if(d.terms_version!=1||std::set<StableId>{d.recognize_node_id,d.accept_node_id,d.revoke_node_id}.size()!=3)return common_failure("DistinctCollateralDeclarationsRequired",d.id);return common_success();}
const DialogueDefinition* dialogue(const InteractionCatalog& c,const StableId& id){const DialogueDefinition* found=nullptr;for(const auto& d:c.dialogues)if(d.id==id){if(found)return nullptr;found=&d;}return found;}
const DialogueNode* node(const DialogueDefinition& d,const StableId& id){const DialogueNode* found=nullptr;for(const auto& n:d.nodes)if(n.id==id){if(found)return nullptr;found=&n;}return found;}
bool selector(const KnownPersonalDialogueSelector& s){return reference(s.source_id)&&(s.kind=="installed_actor"||s.kind=="born_prototype");}
}
Outcome<CollateralControlCatalog> decode_collateral_control_catalog(const BoundaryValue& value){try{auto unique=validate_succession_json_unique(value);if(!unique.ok)return {false,{},unique.error};using namespace boundary;fields(value,{"version","profile","requests"},{},"family_collateral_legacy");if(get_int(value,"version","")!=1||get_string(value,"profile","")!="recognized_collateral_control_v1")unsupported("UnsupportedCollateralControlProfile","");const auto& rows=array(field(value,"requests",""),"requests");if(rows.empty()||rows.size()>4096)fail("InvalidCollateralControlRequestCount","");CollateralControlCatalog out;out.enabled=true;for(const auto& row:rows){fields(row,{"id","template_id","recognize_node_id","accept_node_id","revoke_node_id","terms_version","recognition_scope","control_scope"},{},"collateral_control/request");CollateralControlDefinition d;d.id=get_string(row,"id","");d.template_id=get_string(row,"template_id","");d.recognize_node_id=get_string(row,"recognize_node_id","");d.accept_node_id=get_string(row,"accept_node_id","");d.revoke_node_id=get_string(row,"revoke_node_id","");d.terms_version=get_int(row,"terms_version","");if(get_string(row,"recognition_scope","")!="mutual_collateral_recognition_only"||get_string(row,"control_scope","")!="own_life_control_only")fail("InvalidCollateralControlScope",d.id);auto valid=definition_shape(d);if(!valid.ok)return {false,{},valid.error};if(!out.definitions.insert(d.id,d))fail("DuplicateCollateralControlRequest",d.id);}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_collateral_control_catalog(const CollateralControlCatalog& catalog,const LegacyControlConsentCatalog& original,const InteractionCatalog& interactions,const CollateralControlTemplateRead& templates){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 29, "CollateralControlCatalog", "validate_collateral_control_catalog", &catalog);

    if(!catalog.enabled)return catalog.definitions.empty()?common_success():common_failure("CollateralControlProfileRequired");if(!original.enabled||(original.version!=3&&original.version!=4))return common_failure("CollateralLegacyVersion3Required");if(!interactions.common||!templates)return common_failure("CollateralPersonalTemplateRequired");if(catalog.definitions.empty()||catalog.definitions.size()>4096)return common_failure("InvalidCollateralControlRequestCount");std::set<std::pair<StableId,StableId>> used;
    for(const auto& row:catalog.definitions.rows()){const auto& d=row.second;auto valid=definition_shape(d);if(!valid.ok)return valid;if(row.first!=d.id||original.definitions.find(d.id))return common_failure("CollateralControlRequestCollision",row.first);auto t=templates(d.template_id);if(!t.ok)return {false,{},t.error};if(t.value.id!=d.template_id||!reference(t.value.dialogue_id)||!selector(t.value.listener)||!selector(t.value.provider))return common_failure("CollateralTemplateIdentityMismatch",d.template_id);const auto* talk=dialogue(interactions,t.value.dialogue_id);if(!talk||!talk->context_role.empty())return common_failure("CollateralPrivateDialogueRequired",d.template_id);
        for(const auto* id:{&d.recognize_node_id,&d.accept_node_id,&d.revoke_node_id}){const auto* say=node(*talk,*id);if(!say||say->kind!="say"||say->speaker!="$provider")return common_failure("CollateralProviderDeclarationRequired",*id);if(!used.emplace(d.template_id,*id).second)return common_failure("DuplicateCollateralDeclaration",*id);}
    }return common_success();
}
}
